'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { Check, Copy } from 'lucide-react';
import { type ReactNode, useEffect, useState } from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import {
  cssVarsTheme,
  getHighlighter,
  type TCodeLanguage,
} from '@/registry/default/ui/code/code-themes';
import {
  renderHast,
  type HastNode,
} from '@/registry/default/ui/code/render-hast';

// ---------------------------------------------------------------------------
// Variants
// ---------------------------------------------------------------------------

const codeSnippetVariants = cva(
  'not-prose overflow-hidden rounded-lg font-mono [&>pre]:overflow-x-scroll [&>pre]:[scrollbar-width:none] [&>pre::-webkit-scrollbar]:hidden [&_code]:font-mono',
  {
    variants: {
      size: {
        sm: 'text-sm [&>pre]:p-3',
        md: 'text-base [&>pre]:p-4',
        lg: 'text-lg [&>pre]:p-6',
      },
      bordered: {
        true: 'border border-border',
        false: '',
      },
      isSingleLine: {
        true: '[&>pre]:whitespace-nowrap',
        false: '',
      },
    },
    defaultVariants: {
      size: 'sm',
      bordered: true,
      isSingleLine: false,
    },
  }
);

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

type TCodeSnippetProps = {
  /** Source code to highlight */
  code: string;
  /** Language for syntax highlighting */
  language?: TCodeLanguage;
  /** Show line numbers gutter */
  showLineNumbers?: boolean;
  /** Show copy-to-clipboard button */
  canCopy?: boolean;
  /**
   * Render a top bar showing the language label on the left and the copy
   * button on the right, instead of the floating hover copy button.
   */
  showHeader?: boolean;
  /**
   * Extra actions rendered alongside the copy button — in the header
   * (when `showHeader`) or in the floating hover cluster otherwise.
   */
  headerActions?: ReactNode;
  /** Force a specific theme instead of inheriting from the document */
  isDark?: boolean;
  /** Additional class names on the outer wrapper */
  className?: string;
} & VariantProps<typeof codeSnippetVariants>;

function CodeSnippet({
  code,
  language = 'typescript',
  showLineNumbers = false,
  canCopy = true,
  showHeader = false,
  headerActions,
  size,
  bordered,
  isDark,
  isSingleLine,
  className,
}: TCodeSnippetProps) {
  const [highlighted, setHighlighted] = useState<ReactNode>(null);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      if (!code) {
        setHighlighted(null);

        return;
      }

      const highlighter = await getHighlighter();
      // Fall back to plaintext for any language the highlighter didn't load,
      // so an unsupported `language` renders unhighlighted instead of throwing.
      const safeLang = highlighter.getLoadedLanguages().includes(language)
        ? language
        : 'plaintext';
      // `codeToHast` + `renderHast` keeps the highlighted code as React nodes,
      // so the snippet has no HTML sink and the code text is escaped by React
      // whatever `code` contains.
      const result = highlighter.codeToHast(code, {
        lang: safeLang,
        theme: cssVarsTheme.name!,
        transformers: showLineNumbers
          ? [
              {
                name: 'line-numbers',
                line(node, line) {
                  node.properties['data-line'] = line;
                  node.children.unshift({
                    type: 'element',
                    tagName: 'span',
                    properties: {
                      class: 'line-number',
                      style:
                        'color: var(--shiki-token-comment); margin-right: 1rem; user-select: none; display: inline-block; width: 2em; text-align: right;',
                    },
                    children: [{ type: 'text', value: String(line) }],
                  });
                },
              },
            ]
          : [],
      });

      if (!cancelled) setHighlighted(renderHast(result as HastNode));
    })();

    return () => {
      cancelled = true;
    };
  }, [code, language, showLineNumbers]);

  const handleCopy = async () => {
    await navigator.clipboard.writeText(code.trim());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const dataShikiTheme =
    isDark !== undefined
      ? { 'data-shiki-theme': isDark ? 'dark' : 'light' }
      : {};

  const codeAreaClassName = cn(
    codeSnippetVariants({
      size,
      bordered: showHeader ? false : bordered,
      isSingleLine,
    }),
    showHeader && 'rounded-none'
  );

  const codeArea = highlighted ? (
    <div className={codeAreaClassName}>{highlighted}</div>
  ) : (
    <div className={codeAreaClassName}>
      <pre>
        <code className="font-mono">{code}</code>
      </pre>
    </div>
  );

  const copyButton = canCopy && (
    <Button
      variant="outline"
      size="icon-sm"
      aria-label="Copy code"
      onClick={handleCopy}
      className={cn(
        'text-muted-foreground',
        !showHeader && 'bg-background/80 backdrop-blur-sm'
      )}
    >
      {copied ? <Check /> : <Copy />}
    </Button>
  );

  if (showHeader) {
    return (
      <div
        className={cn(
          'group/code-snippet overflow-hidden rounded-lg',
          bordered !== false && 'border border-border',
          className
        )}
        {...dataShikiTheme}
      >
        <div className="flex items-center justify-between border-b bg-muted/40 p-1.5 pl-3">
          <span className="font-mono text-xs uppercase text-muted-foreground">
            {language}
          </span>
          <div className="flex items-center gap-1">
            {headerActions}
            {copyButton}
          </div>
        </div>
        {codeArea}
      </div>
    );
  }

  return (
    <div
      className={cn('group/code-snippet relative', className)}
      {...dataShikiTheme}
    >
      {codeArea}
      {(copyButton || headerActions) && (
        <div className="absolute right-3 top-3 flex items-center gap-1 opacity-0 transition-opacity group-hover/code-snippet:opacity-100">
          {headerActions}
          {copyButton}
        </div>
      )}
    </div>
  );
}

export { CodeSnippet, codeSnippetVariants, type TCodeSnippetProps };

import { Fragment } from 'react';
import type { CSSProperties, ElementType, ReactNode } from 'react';

const ALLOWED_TAG_NAMES = new Set(['pre', 'code', 'span', 'div', 'br']);

export type HastNode = {
  type: string;
  tagName?: string;
  value?: string;
  properties?: Record<string, unknown>;
  children?: HastNode[];
};

function toCamelCase(property: string) {
  if (property.startsWith('--')) {
    return property;
  }

  return property.replace(/-([a-z])/g, (_, letter: string) =>
    letter.toUpperCase()
  );
}

function parseStyle(style: unknown): CSSProperties | undefined {
  if (typeof style !== 'string') {
    return undefined;
  }

  return style.split(';').reduce<Record<string, string>>((styles, rule) => {
    const [property, ...valueParts] = rule.split(':');
    const value = valueParts.join(':').trim();

    if (property && value) {
      styles[toCamelCase(property.trim())] = value;
    }

    return styles;
  }, {}) as CSSProperties;
}

function normalizePropertyValue(value: unknown) {
  return Array.isArray(value) ? value.join(' ') : value;
}

/**
 * Properties come from the syntax highlighter, never from the highlighted
 * source, so they cannot carry a sink — but the invariant is enforced here
 * rather than assumed, since these keys would let a hast node opt back out of
 * React's escaping or hijack the element identity.
 */
const FORBIDDEN_PROPERTIES = new Set(['dangerouslySetInnerHTML', 'ref', 'key']);

function getReactProps(properties: Record<string, unknown> = {}) {
  return Object.entries(properties).reduce<Record<string, unknown>>(
    (props, [key, value]) => {
      if (FORBIDDEN_PROPERTIES.has(key)) {
        return props;
      }

      if (key === 'class' || key === 'className') {
        props.className = normalizePropertyValue(value);
      } else if (key === 'style') {
        props.style = parseStyle(value);
      } else if (key === 'tabindex') {
        props.tabIndex = Number(value);
      } else {
        props[key] = normalizePropertyValue(value);
      }

      return props;
    },
    {}
  );
}

function renderHastNode(node: HastNode, key: string): ReactNode {
  if (node.type === 'text') {
    return node.value ?? '';
  }

  const children = node.children?.map((child, index) =>
    renderHastNode(child, `${key}-${index}`)
  );

  if (node.type === 'root') {
    return <>{children}</>;
  }

  if (node.type === 'element' && node.tagName) {
    // A syntax highlighter only ever emits these, and React escaping does not
    // help inside a `<script>` or a `<style>` — so an unexpected tag keeps its
    // text and loses the element.
    if (!ALLOWED_TAG_NAMES.has(node.tagName)) {
      return <Fragment key={key}>{children}</Fragment>;
    }

    const Tag = node.tagName as ElementType;

    return (
      <Tag key={key} {...getReactProps(node.properties)}>
        {children}
      </Tag>
    );
  }

  return null;
}

export function renderHast(node: HastNode): ReactNode {
  return renderHastNode(node, 'root');
}
